// a small painting of the whole image from a few of its rows, without downloading the rest:
// read(start, end) resolves to those bytes (end inclusive); resolves to {W, H, data} (RGBA, H = rows,
// channels in the colours of their roles, all on), or null for a file not one to paint
async function thumb(read, rows) {
  let head;
  for (let n = 8192; ; n *= 4) {
    head = await read(0, n - 1);
    const L = layout(new DataView(head), head.byteLength);
    if (L !== undefined || head.byteLength < n || n >= 1 << 20) { head = L; break; }
  }
  const L = head;
  if (!L) return null;
  const H = Math.min(rows, L.H), W = Math.max(1, Math.round((H * L.W) / L.H)), line = L.W * L.bpp;
  const planes = [0, 1, 2].map(() => new Float32Array(W * H)), jobs = [];
  for (let k = 0; k < 3; k++) for (let j = 0; j < H; j++) jobs.push([k, j]);
  // each sampled row averaged into W columns
  const take = async ([k, j]) => {
    const y = Math.floor(((j + 0.5) * L.H) / H), o = L.starts[k] + y * line;
    const dv = new DataView(await read(o, o + line - 1)), p = planes[k];
    for (let x = 0; x < L.W; x++) p[j * W + Math.min(W - 1, Math.floor((x * W) / L.W))] += L.bpp === 2 ? dv.getUint16(2 * x, L.le) : dv.getUint8(x);
  };
  for (let at = 0; at < jobs.length; ) await Promise.all(jobs.slice(at, (at += THUMB_READS)).map(take));
  const role = [];
  role[L.caspr] = CASPR;
  const others = [0, 1, 2].filter((k) => k !== L.caspr), [a, b] = others.map((k) => spread(planes[k]));
  role[others[0]] = a >= b ? DAPI : NAV; role[others[1]] = a >= b ? NAV : DAPI;
  const data = new Uint8ClampedArray(W * H * 4);
  for (let k = 0; k < 3; k++) {
    const p = planes[k], s = Float32Array.from(p).sort();
    const lo = s[Math.floor(s.length * 0.005)], hi = s[Math.floor(s.length * 0.998)], f = 255 / Math.max(1e-9, hi - lo);
    const c = role[k] === NAV ? 0 : role[k] === CASPR ? 1 : 2;
    for (let i = 0; i < p.length; i++) data[4 * i + c] = (p[i] - lo) * f;
  }
  for (let i = 3; i < data.length; i += 4) data[i] = 255;
  return { W, H, data };
}
const THUMB_READS = 16; // rows asked for at once

return { painter, blobArea, thumb };

