      const where = count * size <= 4 ? at + 8 : u32(at + 8);
      if (where + count * size > got) return undefined;
      const read = (k) => (type === 3 ? u16(where + 2 * k) : type === 4 ? u32(where + 4 * k) : dv.getUint8(where + k));
