      if (made.has(f.id)) return;
      pic.file = f; seen.observe(pic);
    };
    return { reset, watch, stop: () => ctl.abort() };
  })();
  $("#drive-open").onclick = () => chosen && enter(chosen);
  $("#drive-dlg").addEventListener("close", () => thumbs.stop());
